from pypdf import PdfReader
import re
for i in [2,3,4,5]:
 t='\n'.join(p.extract_text() for p in PdfReader(f'studies/papers/paper_{i}.pdf').pages)
 print('\nPAPER',i)
 patterns={2:r'(?i)(tamoxifen|hydroxy)',3:r'(?i)(profiling|96 hour|72 hour|microarray)',4:r'(?i)(8–12|sequencing|withdraw|ethanol|continuous|1 μM)',5:r'(?i)(RNA sequencing|RNA-seq|hormone deprivation|4-OH tamoxifen)'}
 for m in re.finditer(patterns[i],t):
  if i==2 and m.start()>12500:continue
  print(t[max(0,m.start()-220):m.end()+500].replace('\n',' '))

